import React from 'react';

const Conclusion = () => {
    return (
        <section>
            <h2>Conclusión</h2>
            <p>
                Recordar la dictadura de los hermanos Tinoco no solo permite conocer un episodio importante del pasado costarricense, 
                sino también reflexionar sobre la relevancia de proteger la democracia, fortalecer las instituciones y promover 
                una ciudadanía informada y participativa.
            </p>
            <p>
                La propuesta “Recordar para defender la democracia” busca precisamente convertir los hallazgos de la investigación 
                en una iniciativa educativa, creativa y socialmente relevante, capaz de comunicar la historia de manera accesible 
                y de generar conciencia sobre su importancia en el presente.
            </p>
        </section>
    );
};

export default Conclusion;
